	//! clip for a clip set (placement family) / action / side mask; armed = rifle in hand (left hand only).
	//! -1 = none (armed both cups: run L, then R)
	static int Find(int clipSet, int action, int mask, bool armed)
	{
		for (int i = 0; i < COUNT; i++)
		{
			if (SetOf(i) != clipSet || ActionOf(i) != action || MaskOf(i) != mask)
				continue;
			if (mask == 1 || ArmedOf(i) == armed)
				return i;
		}
		return -1;
	}

